(436184, 40169, 6172, '<td valign="top">There is a lot of glare in the front of the soup bowl.  Maybe you should cropped the shot closer.</td>', 'There is a lot of glare in the front of the soup bowl.  Maybe you should cropped the shot closer.', '2003-10-01 05:38:58.000000', NULL, 1),
(436185, 40177, 6172, '<td valign="top">I''m not sure you have the right idea of what "Irony" is, but I won''t take off too much for that - I notice many of the english speakers here don''t either.  The photo is rather dark.</td>', 'I''m not sure you have the right idea of what "Irony" is, but I won''t take off too much for that - I notice many of the english speakers here don''t either.  The photo is rather dark.', '2003-10-01 05:40:59.000000', NULL, 1),
(436186, 40132, 6172, '<td valign="top">I like the angle you chose here, and your choice of DOF.  Good shot.</td>', 'I like the angle you chose here, and your choice of DOF.  Good shot.', '2003-10-01 05:42:17.000000', NULL, 1),
(436187, 40168, 6172, '<td valign="top">Very nice, one of the best I''ve seen so far.  Great lighting.</td>', 'Very nice, one of the best I''ve seen so far.  Great lighting.', '2003-10-01 05:43:10.000000', NULL, 1),
