(437272, 40276, 12719, '<td valign="top">ah, double irony with the reversal of the song lyric. clever. I like the composition, except the glass on the left keeps pulling my sight over there and that''s distracing. scary looking knives.</td>', 'ah, double irony with the reversal of the song lyric. clever. I like the composition, except the glass on the left keeps pulling my sight over there and that''s distracing. scary looking knives.', '2003-10-01 18:18:41.000000', NULL, 1),
(437273, 40125, 7628, '<td valign="top">Fun job with the colors and a very "punny" title.  Perhaps a closer crop would serve to focus attention on the subject and the yellow wouldn''t need to be so extreem.</td>', 'Fun job with the colors and a very "punny" title.  Perhaps a closer crop would serve to focus attention on the subject and the yellow wouldn''t need to be so extreem.', '2003-10-01 18:19:36.000000', NULL, 1),
(437275, 39736, 12719, '<td valign="top">ha. I like this one. the colours are punchy, it''s amusing and the composition is nice. drawn to the sign first, read it, follow it down and see the climbing net. v. good.</td>', 'ha. I like this one. the colours are punchy, it''s amusing and the composition is nice. drawn to the sign first, read it, follow it down and see the climbing net. v. good.', '2003-10-01 18:21:53.000000', NULL, 1),
