(437278, 39670, 7628, '<td valign="top">Hairy, brutish and short?  I thought it was 42.  Light from both sides would eliminate the funny shadows.</td>', 'Hairy, brutish and short?  I thought it was 42.  Light from both sides would eliminate the funny shadows.', '2003-10-01 18:23:29.000000', NULL, 1),
(437280, 40087, 7628, '<td valign="top">I like the composition with the boat leaning out of the picture.  Wish the subject was brighter, it is too much in the shadows.</td>', 'I like the composition with the boat leaning out of the picture.  Wish the subject was brighter, it is too much in the shadows.', '2003-10-01 18:25:48.000000', NULL, 1);
