(437590, 40127, 9462, '<td valign="top">See now if the man was rigged up to tow and not the horse, then that would be ironic.</td>', 'See now if the man was rigged up to tow and not the horse, then that would be ironic.', '2003-10-01 20:48:07.000000', NULL, 1),
