(439005, 40367, 10296, '<td valign="top">I love the concept, but it would''ve been better perhaps if you had a poster or whiteboard with the winning numbers, so you could get it in focus</td>', 'I love the concept, but it would''ve been better perhaps if you had a poster or whiteboard with the winning numbers, so you could get it in focus', '2003-10-03 16:53:37.000000', NULL, 1),
(439007, 40346, 10296, '<td valign="top">I think the glare from the light table takes away from this picture, but I like it otherwise.</td>', 'I think the glare from the light table takes away from this picture, but I like it otherwise.', '2003-10-03 16:57:27.000000', NULL, 1),
(439010, 40179, 10078, '<td valign="top">Gimme a break! That''s not irony... more like a missed opportunity or just you being cheap. <br/>DOES NOT MEET CHALLENGE [1]</td>', 'Gimme a break! That''s not irony... more like a missed opportunity or just you being cheap. DOES NOT MEET CHALLENGE [1]', '2003-10-03 17:04:40.000000', NULL, 1),
