(439849, 40028, 6172, '<td valign="top">Without the title there is no irony here.</td>', 'Without the title there is no irony here.', '2003-10-05 19:14:12.000000', NULL, 1),
(439881, 39953, 509, '<td valign="top">Kind of hard to see the irony here.  It looks like a car headlight, but maybe something in the picture to put a firmer emphasis on the "beauty" would help make the connection.  The geometry of the wreckage is interesting though.</td>', 'Kind of hard to see the irony here.  It looks like a car headlight, but maybe something in the picture to put a firmer emphasis on the "beauty" would help make the connection.  The geometry of the wreckage is interesting though.', '2003-10-05 21:26:39.000000', NULL, 1),
