INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(442663, 39821, 5728, '<td valign="top">Could you explain this one perhaps. I looked at it a couple of times but honestly couldn''t find the irony in it.</td>', 'Could you explain this one perhaps. I looked at it a couple of times but honestly couldn''t find the irony in it.', '2003-10-08 09:24:24.000000', NULL, 0),
